<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.id=:id LIMIT 1");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Test round not found.');}$stage=ucfirst((string)$round['round_type']);$types=$round['round_type']==='heats'?['judges'=>'Judges','competitors'=>'Competitors','scoring'=>'Scoring Status','callbacks'=>'Callback Reveal']:($round['round_type']==='semifinal'?['judges'=>'Judges','competitors'=>'Semifinal Competitors','scoring'=>'Scoring Status','finalists'=>'Finalists Reveal']:['judges'=>'Judges','competitors'=>'Finalists','scoring'=>'Scoring Status','results'=>'Final Ranking','winners'=>'Winner Reveal']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Projection Control</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.card{border-radius:15px}.test{letter-spacing:.1em}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">Test Live Screen Projector</span><a class="btn btn-light btn-sm" href="../scoring-tests/select-mode.php">⌂ Test Dashboard</a></div></nav><main class="container py-4"><div class="alert alert-warning fw-bold test">TEST MODE · NOTHING ON THIS SCREEN CAN PUBLISH OFFICIAL BDC RESULTS OR POINTS</div><h1 class="h2 mb-1"><?=e($round['event_name'])?></h1><div class="text-muted mb-4"><?=e(ucwords(str_replace('_',' ',$round['division'])))?> · <?=e($stage)?></div><div class="row g-3"><?php foreach($types as $key=>$label):?><div class="col-md-6"><div class="card shadow-sm h-100"><div class="card-body"><h2 class="h5"><?=e($label)?></h2><p class="text-muted small">Test 9:16 projection using isolated scoring-test data.</p><?php if($key==='competitors'):?><form method="post" action="../stage-display-link.php" target="_blank"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="data_mode" value="test"><button class="btn btn-danger">Generate / Regenerate Test Link</button></form><?php else:?><a class="btn btn-outline-danger" target="_blank" href="test-projection.php?round_id=<?=$roundId?>&type=<?=e($key)?>">Open Test Projection</a><?php endif;?><?php if($key==='winners'):?><div class="d-flex flex-wrap gap-2 mt-3"><?php foreach([5,4,3,2,1] as $p):?><a class="btn btn-dark btn-sm" target="_blank" href="test-projection.php?round_id=<?=$roundId?>&type=winners&place=<?=$p?>">Reveal #<?=$p?></a><?php endforeach;?><a class="btn btn-warning btn-sm" target="_blank" href="test-projection.php?round_id=<?=$roundId?>&type=winners&place=all">Show All Top 5</a></div><?php endif;?></div></div></div><?php endforeach;?></div></main></body></html>